func TestLoomSetKeyWireExport(t *testing.T) {
 c,_:=expressionProtocolTestCompile(t)
 require.Equal(t,int64(125),defines.MORPCLatestVersion)
 for _,typ:=range []types.T{types.T_float32,types.T_float64} {
  arg:=plan2.GetColExpr(typ.ToType().PlanType(),0,0)
  key,err:=plan2.BindFuncExprImplByPlanExpr(c.proc.Ctx,"set_operation_float_key",[]*planpb.Expr{arg});require.NoError(t,err)
  id,_:=function.DecodeOverloadID(key.GetF().Func.Obj);require.Equal(t,int32(602),id)
  control,err:=plan2.BindFuncExprImplByPlanExpr(c.proc.Ctx,"abs",[]*planpb.Expr{arg});require.NoError(t,err)
  division,err:=plan2.BindFuncExprImplByPlanExpr(c.proc.Ctx,"div",[]*planpb.Expr{plan2.GetColExpr(types.New(types.T_decimal64,10,3).PlanType(),0,0),plan2.GetColExpr(types.T_uint64.ToType().PlanType(),0,1)});require.NoError(t,err)
  temporal,err:=plan2.BindFuncExprImplByPlanExpr(c.proc.Ctx,"timestamp",[]*planpb.Expr{plan2.GetColExpr(types.T_datetime.ToTypeWithScale(3).PlanType(),0,3)});require.NoError(t,err)
  second,err:=plan2.BindFuncExprImplByPlanExpr(c.proc.Ctx,"timestampadd_second_interval",[]*planpb.Expr{plan2.GetColExpr(types.New(types.T_decimal64,18,7).PlanType(),0,4)});require.NoError(t,err)
  p:=&pipeline.Pipeline{InstructionList:[]*pipeline.Instruction{{ProjectList:[]*planpb.Expr{key,control,division,temporal,second}}}}
  data,err:=p.Marshal();require.NoError(t,err)
  require.NoError(t,os.WriteFile(filepath.Join(os.Getenv("MO_LOOM_PROBE_DIR"),typ.String()+".wire"),data,0600))
  t.Logf("candidate bound %s overload=%d bytes=%d",typ,key.GetF().Func.Obj,len(data))
 }
}
func TestLoomObservedMainWorkerExclusion(t *testing.T) {
 data,err:=os.ReadFile(filepath.Join(os.Getenv("MO_LOOM_PROBE_DIR"),"main-response.wire"));require.NoError(t,err)
 var response query.Response;require.NoError(t,response.Unmarshal(data));require.Equal(t,int64(124),response.GetProtocolVersion.Version)
 for _,typ:=range []types.T{types.T_float32,types.T_float64} {
  t.Run(typ.String(),func(t *testing.T){
   c,client:=expressionProtocolTestCompile(t)
   data,err:=os.ReadFile(filepath.Join(os.Getenv("MO_LOOM_PROBE_DIR"),typ.String()+".wire"));require.NoError(t,err)
   var p pipeline.Pipeline;require.NoError(t,p.Unmarshal(data));expr:=p.InstructionList[0].ProjectList[0]
   client.customResponse=true;client.response=&response
   c.execType=plan2.ExecTypeAP_MULTICN;c.cnList=engine.Nodes{{Id:"old-worker",Addr:"remote:6001",Mcpu:4}}
   require.NoError(t,c.constrainRemoteExpressionWorkers(&planpb.Query{Nodes:[]*planpb.Node{{PhysicalEqualityKeyList:[]*planpb.Expr{expr}}},Steps:[]int32{0}}))
   require.Equal(t,plan2.ExecTypeAP_ONECN,c.execType)
   op:=projection.NewArgument();defer op.Release();op.ProjectList=[]*planpb.Expr{expr}
   scope:=&Scope{Magic:Remote,Proc:c.proc,NodeInfo:engine.Node{Id:"old-worker",Addr:"remote:6001"},RootOp:op}
   encoded,err:=encodeRemoteScope(scope,c.proc);require.ErrorContains(t,err,"version 125");require.Nil(t,encoded)
   require.Positive(t,client.calls);require.Equal(t,client.calls,client.releases)
   t.Logf("actual official response version=%d placement=coordinator sendErr=%v",response.GetProtocolVersion.Version,err)
  })
 }
}
